224: static void fairplay_exit_site(int status,const char *kind)
225: {
226:     char line[560];
227:     int n=snprintf(line,sizeof(line),"Pong A2: %s(%d) site:",kind,status);
228:     void *frame=__builtin_frame_address(0);
229:     for(unsigned i=0;n>0&&(size_t)n<sizeof(line)-24&&frame&&i<12;i++) {
230:         void **pair=(void **)frame;
231:         uintptr_t site=(uintptr_t)pair[1];
232:         /* v66 bug: the filter was written at 1-3 TiB while real user
233:          * code addresses (executable, cache, this library) sit between
234:          * 4 and 12 GiB - every frame was dropped. Bound to that range
235:          * and stop at the first implausible value. */
236:         if(site<0x100000000ULL||site>=0x300000000ULL)break;
237:         n+=snprintf(line+n,sizeof(line)-(size_t)n," %llx",
238:                     (unsigned long long)site);
239:         frame=pair[0];
240:     }
241:     if(n>0)pong_a2_line(line);
242: }
